def _rows(text):
    return R.parse_text(text, "t")


def test_format_a_areas_match_and_bottom_sowing_excluded():
    rows = _rows(FMT_A)
    assert len(rows) == 6
    assert all(r["qc"] == "ok" for r in rows)
    assert [r["area_decl_ha"] for r in rows] == [2.9067, 5.4727, 1.36, 2.5573, 1.6753, 1.4]
    assert rows[1]["street"] == "大李家街道" and rows[1]["culture"] == "筏吊式"
    assert [r["raft_visible"] for r in rows] == [True] * 5 + [False]     # 第 6 宗是滩涂底播


def test_format_b_interleaved_cells_and_two_part_parcel():
    rows = _rows(FMT_B)
    assert len(rows) == 4 and all(r["qc"] == "ok" for r in rows)
    assert len(rows[0]["rings"]) == 2                     # 1–4、5–8 两块，连续编号
    assert rows[0]["mgmt_no"] == "2024D21021353292" and rows[0]["street"] == "杏树街道"
    assert rows[1]["mgmt_no"] == "2023D21021322913;2025D21021320863" and rows[1]["sea_mode"] == "海面海底"
    assert rows[2]["area_decl_ha"] == 19.9081                # 备注里的"18.262公顷"不能当面积
    assert rows[3]["area_decl_ha"] == 11.6617 and rows[3]["n_pts"] == 7


def test_format_c_excel_csv():
    rows = _rows(FMT_C)
    assert len(rows) == 4 and all(r["qc"] == "ok" for r in rows)
    assert rows[0]["culture"] == "筏吊式、网箱" and rows[0]["app_type"] == "续期"
    assert rows[1]["street"] == "金石滩街道" and rows[1]["area_decl_ha"] == 0.1107
    assert rows[3]["area_decl_ha"] == 9.5677                 # "6.2667、3.3,9.5677"：取申请面积
    assert not rows[2]["raft_visible"] and not rows[3]["raft_visible"]   # 海底


def test_run_dedupes_across_notices(tmp_path):
    (tmp_path / "2025-01-01_a.txt").write_text(FMT_A, encoding="utf-8")
    (tmp_path / "2025-06-01_a_again.txt").write_text(FMT_A, encoding="utf-8")   # 同一批地块再次公示
    (tmp_path / "2026-02-03_c.csv").write_text(FMT_C, encoding="utf-8")
    items, parcels = R.run(tmp_path)
    assert len(items) == 16 and len(parcels) == 10
    again = [p for p in parcels if p["n_notices"] == 2]
    assert len(again) == 6 and all(p["first_notice"] == "2025-01-01" for p in again)
    assert parcels[0]["pid"] == "DL00001"
    assert "可直接用于卫星筛查" in R.qc_report(items, parcels)
